import{_ as t,o as i,c as n,a5 as a}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse('{"title":"Consistency Plan Template","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/consistency-plan.en.md","filePath":"public/downloads/worksheets/consistency-plan.en.md","lastUpdated":1795488252000}'),o={name:"public/downloads/worksheets/consistency-plan.en.md"};function r(s,e,l,d,c,h){return i(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="consistency-plan-template" tabindex="-1">Consistency Plan Template <a class="header-anchor" href="#consistency-plan-template" aria-label="Permalink to &quot;Consistency Plan Template&quot;">​</a></h1><p>Use this template for one action experiment with an end date. It supplements the <a href="https://byoungd.github.io/up/en/templates/rhythm-ledger" target="_blank" rel="noreferrer">Rhythm Ledger</a>: the ledger tracks weekly capacity and obstacles, while this experiment card specifies one change, its acceptance criteria, and conditions for stopping. If you already maintain a ledger, reference the relevant records instead of copying them. Return the conclusion to the ledger when the experiment ends.</p><p>This is a practical tool, not a psychological assessment or a guarantee that a habit will form within a fixed number of days. Fill in what you actually know and leave unknowns for verification. There is no need to add tasks merely to complete the form.</p><p>Read <a href="https://byoungd.github.io/up/en/threads/practice/discipline-and-consistency" target="_blank" rel="noreferrer">Discipline and Consistency in Practice</a> to choose a problem to investigate. Keep using the arrangements in <a href="https://byoungd.github.io/up/en/threads/part-4/daily-system" target="_blank" rel="noreferrer">Daily Systems</a> and <a href="https://byoungd.github.io/up/en/threads/part-4/rhythm-and-compounding" target="_blank" rel="noreferrer">Rhythm and Compounding</a> instead of maintaining another schedule. Keep state and work locations in your <a href="https://byoungd.github.io/up/en/templates/learning-state" target="_blank" rel="noreferrer">Learning State</a>, and put weekly conclusions in the <a href="https://byoungd.github.io/up/en/templates/weekly-review" target="_blank" rel="noreferrer">Weekly Review</a>. Store personal records in your own notes and use evidence locations that do not disclose sensitive information.</p><h2 id="copyable-template" tabindex="-1">Copyable Template <a class="header-anchor" href="#copyable-template" aria-label="Permalink to &quot;Copyable Template&quot;">​</a></h2><h3 id="consistency-plan-—-one-goal" tabindex="-1">Consistency Plan — [One Goal] <a class="header-anchor" href="#consistency-plan-—-one-goal" aria-label="Permalink to &quot;Consistency Plan — \\[One Goal]&quot;">​</a></h3><p>Updated: YYYY-MM-DD<br> Cycle: YYYY-MM-DD to YYYY-MM-DD<br> Review date or condition:</p><h4 id="goal-and-evidence" tabindex="-1">Goal and Evidence <a class="header-anchor" href="#goal-and-evidence" aria-label="Permalink to &quot;Goal and Evidence&quot;">​</a></h4><ul><li>Why this is worth doing now:</li><li>The one outcome for this cycle:</li><li>Current baseline and sample location:</li><li>Acceptance criteria that can be observed or checked:</li><li>Explicitly outside this cycle&#39;s scope:</li></ul><h4 id="realistic-budget" tabindex="-1">Realistic Budget <a class="header-anchor" href="#realistic-budget" aria-label="Permalink to &quot;Realistic Budget&quot;">​</a></h4><ul><li>Existing work, caring, and other responsibilities:</li><li>Available windows and total time for this cycle:</li><li>Time for preparation, execution, and feedback:</li><li>Buffer window, if any:</li><li>Time or resources I will not reallocate:</li><li>Conditions requiring agreement or still uncertain:</li></ul><h4 id="starting-point" tabindex="-1">Starting Point <a class="header-anchor" href="#starting-point" aria-label="Permalink to &quot;Starting Point&quot;">​</a></h4><ul><li>After [an identifiable event]:</li><li>At [an available place], open [resource/file]:</li><li>First do [one specific action]:</li><li>Main obstacle and the one change for this cycle:</li><li>Contacts or alerts that must remain available:</li><li>Next step to save before finishing:</li></ul><h4 id="three-versions" tabindex="-1">Three Versions <a class="header-anchor" href="#three-versions" aria-label="Permalink to &quot;Three Versions&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Version</th><th>When to use it</th><th>Action and stopping condition</th><th>What to save</th></tr></thead><tbody><tr><td>Minimum</td><td></td><td></td><td></td></tr><tr><td>Standard</td><td></td><td></td><td></td></tr><tr><td>Extended, optional</td><td></td><td></td><td></td></tr></tbody></table><ul><li>Practice or validation the minimum version cannot replace:</li><li>Maximum time per session:</li><li>Conditions for reducing the workload:</li><li>Conditions for pausing:</li></ul><h4 id="restart-after-an-interruption" tabindex="-1">Restart After an Interruption <a class="header-anchor" href="#restart-after-an-interruption" aria-label="Permalink to &quot;Restart After an Interruption&quot;">​</a></h4><ul><li>State file and most recent work locations:</li><li>How to reassess ability at the first restart:</li><li>First bounded task after the break:</li><li>Next reassessment date or condition:</li><li>How to adjust scope or negotiate if a deadline is affected:</li></ul><h4 id="cycle-log" tabindex="-1">Cycle Log <a class="header-anchor" href="#cycle-log" aria-label="Permalink to &quot;Cycle Log&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Date</th><th>Planned action</th><th>Actual output and location</th><th>Obstacle/cost</th><th>Next step</th></tr></thead></table><h4 id="cycle-review" tabindex="-1">Cycle Review <a class="header-anchor" href="#cycle-review" aria-label="Permalink to &quot;Cycle Review&quot;">​</a></h4><ul><li>What changed from the baseline, with evidence:</li><li>What I still cannot independently explain or complete:</li><li>Whether the arrangement exceeded the budget or displaced responsibilities:</li><li>Conditions for continuing:</li><li>Conditions for changing the method:</li><li>Conditions for pausing or stopping:</li><li>Decision for this cycle and supporting reasons:</li><li>The one change for the next cycle:</li></ul><h2 id="worked-example-improving-an-english-project-introduction-in-four-weeks" tabindex="-1">Worked Example: Improving an English Project Introduction in Four Weeks <a class="header-anchor" href="#worked-example-improving-an-english-project-introduction-in-four-weeks" aria-label="Permalink to &quot;Worked Example: Improving an English Project Introduction in Four Weeks&quot;">​</a></h2><p><strong>This example is fictional. Its schedule and workload only demonstrate how to fill in the template.</strong> The learner needs to explain an AI note-organizing tool in English during a team discussion. The plan takes work and family responsibilities into account.</p><h3 id="consistency-plan-—-english-project-introduction" tabindex="-1">Consistency Plan — English Project Introduction <a class="header-anchor" href="#consistency-plan-—-english-project-introduction" aria-label="Permalink to &quot;Consistency Plan — English Project Introduction&quot;">​</a></h3><p>Updated: 2026-09-19<br> Cycle: 2026-09-21 to 2026-10-18<br> Review date or condition: Every Sunday, or earlier if work arrangements change.</p><h4 id="goal-and-evidence-1" tabindex="-1">Goal and Evidence <a class="header-anchor" href="#goal-and-evidence-1" aria-label="Permalink to &quot;Goal and Evidence&quot;">​</a></h4><ul><li>Why this is worth doing now: Explain the project&#39;s purpose and limitations at the next team discussion.</li><li>The one outcome for this cycle: Independently give a 90-second introduction and answer two follow-up questions.</li><li>Current baseline and sample location: The first recording lasts about 50 seconds; examples/baseline.m4a.</li><li>Acceptance criteria: A listener can restate the purpose, intended user, and one limitation. Answer two follow-ups in my own words and explicitly acknowledge unknowns.</li><li>Explicitly outside this cycle&#39;s scope: Accent imitation, a full product pitch, and new feature development.</li></ul><h4 id="realistic-budget-1" tabindex="-1">Realistic Budget <a class="header-anchor" href="#realistic-budget-1" aria-label="Permalink to &quot;Realistic Budget&quot;">​</a></h4><ul><li>Existing work, caring, and other responsibilities: Family commitments make weekday evenings unpredictable.</li><li>Available windows and total time for this cycle: Two 20-minute lunches and one 20-minute weekend session per week; 240 minutes across four weeks.</li><li>Time for preparation, execution, and feedback: 10 / 35 / 15 minutes per week.</li><li>Buffer window: At most one extra 10-minute window each week. It may not be available and is excluded from the basic budget.</li><li>Time or resources I will not reallocate: Agreed family time; no staying up late to make up missed sessions.</li><li>Conditions requiring agreement or still uncertain: Agree on the weekend recording window in advance; check whether a feedback partner is available.</li></ul><h4 id="starting-point-1" tabindex="-1">Starting Point <a class="header-anchor" href="#starting-point-1" aria-label="Permalink to &quot;Starting Point&quot;">​</a></h4><ul><li>After lunch on Tuesday and Thursday, if the break is still available:</li><li>At my desk, open notes/project-intro.md:</li><li>First do: Write one point I want to explain today.</li><li>Main obstacle and the one change for this cycle: Materials are scattered; use this single outline.</li><li>Contacts or alerts that must remain available: Work on-call messages and urgent family contact.</li><li>Next step to save before finishing: The unclear point and the example to use next time.</li></ul><h4 id="three-versions-1" tabindex="-1">Three Versions <a class="header-anchor" href="#three-versions-1" aria-label="Permalink to &quot;Three Versions&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Version</th><th>When to use it</th><th>Action and stopping condition</th><th>What to save</th></tr></thead><tbody><tr><td>Minimum</td><td>Only 5 minutes available</td><td>Write three explanatory sentences and flag one uncertain expression</td><td>Three sentences and one question</td></tr><tr><td>Standard</td><td>20 minutes available</td><td>Revise the outline at lunch; on the weekend, record, listen, and correct one point</td><td>Outline or recording, with a revision note</td></tr><tr><td>Extended</td><td>Weekly tasks are done and the buffer is available</td><td>Answer one follow-up using different wording; stop at 10 minutes</td><td>One question-and-answer record</td></tr></tbody></table><ul><li>Practice or validation the minimum version cannot replace: Speaking aloud, responding to spontaneous questions, and feedback from an actual listener.</li><li>Maximum time per session: 20 minutes, with a separate 10-minute limit for the extended version.</li><li>Conditions for reducing the workload: Unexpected work takes one window; retain only one key point.</li><li>Conditions for pausing: No available windows this week; save the state for next week&#39;s review.</li></ul><h4 id="restart-after-an-interruption-1" tabindex="-1">Restart After an Interruption <a class="header-anchor" href="#restart-after-an-interruption-1" aria-label="Permalink to &quot;Restart After an Interruption&quot;">​</a></h4><ul><li>State file and most recent work locations: notes/learning-state.md; recordings/.</li><li>How to reassess ability at the first restart: Speak for 30 seconds without the outline, compare with the baseline, and record gaps.</li><li>First bounded task after the break: Explain one use of the tool, save the recording, and stop.</li><li>Next reassessment date or condition: The next Sunday, or after the work roster is confirmed.</li><li>How to adjust scope or negotiate if a deadline is affected: Use a shorter introduction and agree with the team in advance; do not claim the full practice plan is complete.</li></ul><h4 id="cycle-log-1" tabindex="-1">Cycle Log <a class="header-anchor" href="#cycle-log-1" aria-label="Permalink to &quot;Cycle Log&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Date</th><th>Planned action</th><th>Actual output and location</th><th>Obstacle/cost</th><th>Next step</th></tr></thead><tbody><tr><td>2026-09-22</td><td>Write points about purpose and users</td><td>Three sentences in notes/project-intro.md</td><td>An unexpected message left 5 minutes; used the minimum version</td><td>Check one expression next time</td></tr><tr><td>2026-09-26</td><td>Make the weekend recording</td><td>recordings/week-1.m4a, 60 seconds</td><td>The limitation was unclear; stayed within budget</td><td>First write one specific limitation</td></tr></tbody></table><h4 id="cycle-review-1" tabindex="-1">Cycle Review <a class="header-anchor" href="#cycle-review-1" aria-label="Permalink to &quot;Cycle Review&quot;">​</a></h4><ul><li>What changed from the baseline, with evidence: The first week&#39;s recording includes purpose and users; listener understanding has not yet been checked.</li><li>What I still cannot independently explain or complete: The tool&#39;s limitation; the two spontaneous follow-ups have not been practiced.</li><li>Whether the arrangement exceeded the budget or displaced responsibilities: Within budget in week one, but Tuesday&#39;s window lasted only 5 minutes.</li><li>Conditions for continuing: The goal remains useful, windows remain available, and recordings or feedback show specific improvements.</li><li>Conditions for changing the method: If practice remains memorized recitation, add explanations without notes and feedback.</li><li>Conditions for pausing or stopping: Pause if windows disappear; reassess the purpose if the team discussion is canceled.</li><li>Decision for this cycle and supporting reasons: Continue into the next week and address the limitation first. Current records cannot establish the four-week outcome.</li><li>The one change for the next cycle: Ask a feedback partner to restate the limitation in one sentence. If they are unavailable, record that feedback is missing.</li></ul><p>The first week&#39;s records show an incomplete result: the goal has not yet been met, but the next step is clear. The final review still needs four weeks of evidence. The plan itself is not evidence of its effectiveness.</p><h2 id="ask-ai-to-organize-evidence-not-invent-progress" tabindex="-1">Ask AI to Organize Evidence, Not Invent Progress <a class="header-anchor" href="#ask-ai-to-organize-evidence-not-invent-progress" aria-label="Permalink to &quot;Ask AI to Organize Evidence, Not Invent Progress&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Below are my consistency plan and actual records for this cycle. Check for contradictions in the time budget, whether acceptance criteria are observable, and whether I am treating the minimum version as a substitute for complete practice. Identify evidence gaps. Do not invent completed tasks or feedback. Respect the existing responsibilities and suggest only one adjustment for the next cycle. If key facts are missing, clearly identify what I need to verify.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Paste the plan and records]</span></span></code></pre></div><p>Before accepting a suggestion, check your calendar, actual work, and other people&#39;s availability. Revising the plan to fit reality is part of using this template.</p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/consistency-plan" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-09-19. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>`,47)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
